module.exports = [{"id_kalimat":"amogenz_tasrif_012","teks_kalimat":"خَافَ","analysis":[{"id_lafadz":"amogenz_lafadz_012","word":"خَافَ","steps":{"1":{"question":"Apa Wazan asli dan Bab dari lafadz خَافَ dalam Tasrif Ishtilahi?","options":["Bab 4 (فَعِلَ - يَفْعَلُ) dengan wazan asal خَوِفَ - يَخْوَفُ","Bab 1 (فَعَلَ - يَفْعُلُ) dengan wazan asal خَوَفَ - يَخْوُفُ","Bab 2 (فَعَلَ - يَفْعِلُ) dengan wazan asal خَيَفَ - يَخْيِفُ","Bab 3 (فَعَلَ - يَفْعَلُ) dengan wazan asal خَوَفَ - يَخْوَفُ"],"correct":"Bab 4 (فَعِلَ - يَفْعَلُ) dengan wazan asal خَوِفَ - يَخْوَفُ","explanation":"Lafadz خَافَ tergolong Bab 4 Thulathi Mujarrad (فَعِلَ - يَفْعَلُ). Bentuk aslinya adalah خَوِفَ - يَخْوَفُ sebelum proses i'lal."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz خَافَ?","options":["خَافَ - يَخَافُ - خَوْفًا - فَهُوَ خَائِفٌ - وَذَاكَ مَخُوفٌ - خَفْ - لَا تَخَفْ - مَخَافٌ - مَخَافٌ - مِخْوَافٌ","خَافَ - يَخُوفُ - خَوْفًا - فَهُوَ خَائِفٌ - وَذَاكَ مَخُوفٌ - خُفْ - لَا تَخُوفْ - مَخَافٌ - مَخَافٌ - مِخْوَافٌ","خَوِفَ - يَخْوَفُ - خَوْفًا - فَهُوَ خَاوِفٌ - وَذَاكَ مَخْوُوفٌ - اِخْوَفْ - لَا تَخْوَفْ - مَخْوَفٌ - مَخْوَفٌ - مِخْوَافٌ","خَافَ - يَخَافُ - خِيفَةً - فَهُوَ مَخُوفٌ - وَذَاكَ خَائِفٌ - خَفْ - لَا تَخَفْ - مَخُوفٌ - مَخُوفٌ - مِخْوَافٌ"],"correct":"خَافَ - يَخَافُ - خَوْفًا - فَهُوَ خَائِفٌ - وَذَاكَ مَخُوفٌ - خَفْ - لَا تَخَفْ - مَخَافٌ - مَخَافٌ - مِخْوَافٌ","explanation":"Deretan Ishtilahi ter-i'lal dari خَافَ: Madhi خَافَ, Mudhori' يَخَافُ, Masdar خَوْفًا, Isim Fa'il خَائِفٌ, Isim Maf'ul مَخُوفٌ, Amr خَفْ, Nahi لَا تَخَفْ, Zaman/Makan مَخَافٌ, Isim Alat مِخْوَافٌ."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz خَافَ ketika bertemu dhomir Anta (أَنْتَ)?","options":["خِفْتَ","خَفْتَ","خُفْتَ","خَوِفْتَ"],"correct":"خِفْتَ","explanation":"Ketika bersambung dhomir rafa' mutaharrik (أَنْتَ), lam fi'il sukun (خَافْتَ) -> Alif dibuang karena iltiqa' sakinain (خَفْتَ) -> Fa' fi'il (خ) di-kasrah-kan menjadi خِفْتَ untuk menunjukkan bahwa 'ain fi'il aslinya berharakat kasrah (خَوِفَ Bab 4)."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz خَافَ ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["تَخَافُونَ","تَخُوفُونَ","تَخْوَفُونَ","تَخِيفُونَ"],"correct":"تَخَافُونَ","explanation":"Untuk dhomir أَنْتُمْ, Fi'il Mudhori' يَخَافُ diawali Ta' mudhoro'ah dan diakhiri Wawu Jama' serta Nun Tsubut, menjadi تَخَافُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Ajwaf Wawi Bab 4 pada pola tasrifan lafadz خَافَ?","options":["Wawu pada خَوِفَ berharakat sesudah fathah diganti Alif (خَافَ); sedangkan pada mudhori' يَخْوَفُ harakat fathah Wawu dipindah ke fa' fi'il lalu Wawu diganti Alif (يَخَافُ)","Huruf Wawu dibuang di seluruh bentuk tasrifan tanpa sisa","Huruf Wawu diganti Ya' pada Fi'il Madhi maupun Mudhori'","Tidak mengalami proses I'lal sama sekali"],"correct":"Wawu pada خَوِفَ berharakat sesudah fathah diganti Alif (خَافَ); sedangkan pada mudhori' يَخْوَفُ harakat fathah Wawu dipindah ke fa' fi'il lalu Wawu diganti Alif (يَخَافُ)","explanation":"Pada Madhi خَوِفَ, Wawu bergerak setelah fathah diubah jadi Alif (خَافَ). Pada Mudhori' يَخْوَفُ, fathah Wawu dipindah ke Kha' lalu Wawu disesuaikan menjadi Alif (يَخَافُ)."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz خَافَ untuk dhomir Anta (أَنْتَ)?","options":["خَفْ dan لَا تَخَفْ","خَافْ dan لَا تَخَافْ","خِفْ dan لَا تَخِفْ","اِخْوَفْ dan لَا تَخْوَفْ"],"correct":"خَفْ dan لَا تَخَفْ","explanation":"Dari mudhori' majzum تَخَافْ, buang huruf mudhoro'ah -> tersisa خَافْ -> Alif dibuang karena iltiqa' sakinain (pertemuan Alif sukun dan Fa' sukun) -> menjadi خَفْ. Nahinya لَا تَخَفْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz خَافَ?","options":["خَائِفٌ dan مَخُوفٌ","خَاوِفٌ dan مَخْوُوفٌ","خَائِفٌ dan مَخِيفٌ","مَخُوفٌ dan خَائِفٌ"],"correct":"خَائِفٌ dan مَخُوفٌ","explanation":"Isim Fa'il asal خَاوِفٌ -> Wawu diganti Hamzah sesudah Alif Zaidah (خَائِفٌ). Isim Maf'ul asal مَخْوُوفٌ -> transfer harakat dhommah Wawu ke Kha' lalu satu Wawu dibuang karena iltiqa' sakinain menjadi مَخُوفٌ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz خَافَ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["خِيفَ (Madhi) dan يُخَافُ (Mudhori')","خُوفَ (Madhi) dan يُخْوَفُ (Mudhori')","خُوِفَ (Madhi) dan يُخَافُ (Mudhori')","خِيفَ (Madhi) dan يُخِيفُ (Mudhori')"],"correct":"خِيفَ (Madhi) dan يُخَافُ (Mudhori')","explanation":"Madhi Majhul asal خُوِفَ -> kasrah Wawu dipindah ke Kha' dan Wawu diganti Ya' menjadi خِيفَ. Mudhori' Majhul asal يُخْوَفُ -> fathah Wawu dipindah ke Kha' dan Wawu diganti Alif menjadi يُخَافُ."},"9":{"question":"Mengapa fa' fi'il pada lafadz خَافَ di-kasrah-kan menjadi خِفْتَ saat bersambung dhomir rafa' mutaharrik dan bagaimana bentuk Isim Zaman/Makan-nya?","options":["Di-kasrah-kan (خِفْتَ) sebagai pembeda bahwa 'ain fi'il aslinya berharakat kasrah (Bab 4 فَعِلَ), dan Isim Zaman/Makan-nya adalah مَخَافٌ (asal مَخْوَفٌ)","Di-kasrah-kan karena Wawu diganti Ya'; dan Isim Zaman/Makan-nya adalah مَخِيفٌ","Di-kasrah-kan untuk menyamakan dengan Bab 1; dan Isim Zaman/Makan-nya adalah مَخُوفٌ","Di-kasrah-kan tanpa sebab khusus; dan Isim Zaman/Makan-nya adalah مِخْوَافٌ"],"correct":"Di-kasrah-kan (خِفْتَ) sebagai pembeda bahwa 'ain fi'il aslinya berharakat kasrah (Bab 4 فَعِلَ), dan Isim Zaman/Makan-nya adalah مَخَافٌ (asal مَخْوَفٌ)","explanation":"Pada Ajwaf Bab 4 (فَعِلَ - يَفْعَلُ), fa' fi'il di-kasrah-kan (خِفْتَ) saat bertemu dhomir rafa' mutaharrik untuk membedakan dari Bab 1 (فَعَلَ - يَفْعُلُ) yang di-dhommah-kan (قُلْتُ). Isim Zaman/Makan مَخْوَفٌ dipindah fathah-nya ke Kha' lalu Wawu jadi Alif (مَخَافٌ)."}}}]},{"id_kalimat":"amogenz_tasrif_013","teks_kalimat":"طَوَى","analysis":[{"id_lafadz":"amogenz_lafadz_013","word":"طَوَى","steps":{"1":{"question":"Apa Wazan asli dan Bab dari lafadz طَوَى dalam Tasrif Ishtilahi?","options":["Bab 2 (فَعَلَ - يَفْعِلُ) dengan wazan asal طَوَيَ - يَطْوِيُ","Bab 1 (فَعَلَ - يَفْعُلُ) dengan wazan asal طَوَوَ - يَطْوُوُ","Bab 3 (فَعَلَ - يَفْعَلُ) dengan wazan asal طَوَيَ - يَطْوَيُ","Bab 4 (فَعِلَ - يَفْعَلُ) dengan wazan asal طَوِيَ - يَطْوَيُ"],"correct":"Bab 2 (فَعَلَ - يَفْعِلُ) dengan wazan asal طَوَيَ - يَطْوِيُ","explanation":"Lafadz طَوَى tergolong Bab 2 Thulathi Mujarrad (فَعَلَ - يَفْعِلُ). Bentuk aslinya sebelum proses i'lal adalah طَوَيَ - يَطْوِيُ."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz طَوَى?","options":["طَوَى - يَطْوِي - طَيًّا - فَهُوَ طَاوٍ - وَذَاكَ مَطْوِيٌّ - اِطْوِ - لَا تَطْوِ - مَطْوًى - مَطْوًى - مِطْوًى","طَوَى - يَطْوَى - طَيًّا - فَهُوَ طَاوٍ - وَذَاكَ مَطْوًى - اِطْوَ - لَا تَطْوَ - مَطْوًى - مَطْوًى - مِطْوًى","طَوَى - يَطْوِي - طَوَايَةً - فَهُوَ مَطْوِيٌّ - وَذَاكَ طَاوٍ - اِطْوِ - لَا تَطْوِ - مَطْوِيٌّ - مَطْوِيٌّ - مِطْوًى","طَوَيَ - يَطْوِيُ - طَيْيًا - فَهُوَ طَاوِيٌ - وَذَاكَ مَطْوُويٌ - اِطْوِيْ - لَا تَطْوِيْ - مَطْوَيٌ - مَطْوَيٌ - مِطْوَيٌ"],"correct":"طَوَى - يَطْوِي - طَيًّا - فَهُوَ طَاوٍ - وَذَاكَ مَطْوِيٌّ - اِطْوِ - لَا تَطْوِ - مَطْوًى - مَطْوًى - مِطْوًى","explanation":"Tasrif Ishtilahi ter-i'lal dari طَوَى: Madhi طَوَى, Mudhori' يَطْوِي, Masdar طَيًّا, Isim Fa'il طَاوٍ, Isim Maf'ul مَطْوِيٌّ, Amr اِطْوِ, Nahi لَا تَطْوِ, Zaman/Makan مَطْوًى, Isim Alat مِطْوًى."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz طَوَى ketika bertemu dhomir Hum (هُمْ)?","options":["طَوَوْا","طَوَيُوا","طَوُوا","طَوَايُوا"],"correct":"طَوَوْا","explanation":"Bentuk asal طَوَيُوا (dhomir هُمْ) mengalami pembuangan Ya' lam fi'il karena iltiqa' sakinain dengan Wawu Jama', dan Wawu 'ain fi'il tetap berharakat fathah untuk menandai huruf yang dibuang adalah Ya', menjadi طَوَوْا."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz طَوَى ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["تَطْوُونَ","تَطْوِيُونَ","تَطْوَوُونَ","تَطْوِينَ"],"correct":"تَطْوُونَ","explanation":"Asalnya تَطْوِيُونَ (dhomir أَنْتُمْ), harakat dhommah Ya' dibuang karena itsqal, lalu Ya' dibuang karena iltiqa' sakinain dengan Wawu Jama', sehingga tersisa Wawu 'ain fi'il + Wawu Jama' + Nun menjadi تَطْوُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Lafif Maqrun pada pola tasrifan lafadz طَوَى?","options":["Memiliki dua huruf 'illat berurutan ('Ain fi'il Wawu dan Lam fi'il Ya'). Wawu ('ain fi'il) tetap shahih/selamat, sedangkan Ya' (lam fi'il) di-i'lal seperti Bina' Naqish","Kedua huruf 'illat-nya di-idgham-kan menjadi satu huruf bertasydid di seluruh tasrifan","Wawu dibuang pada fi'il mudhori' dan Ya' tetap utuh","Kedua huruf 'illat-nya dibuang sekaligus pada bentuk Fi'il Madhi"],"correct":"Memiliki dua huruf 'illat berurutan ('Ain fi'il Wawu dan Lam fi'il Ya'). Wawu ('ain fi'il) tetap shahih/selamat, sedangkan Ya' (lam fi'il) di-i'lal seperti Bina' Naqish","explanation":"Bina' Lafif Maqrun pada lafadz طَوَى memperlakukan 'ain fi'il (Wawu) secara utuh/shahih, sementara lam fi'il (Ya') mengikuti hukum i'lal Bina' Naqish Ya'i."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz طَوَى untuk dhomir Anta (أَنْتَ)?","options":["اِطْوِ dan لَا تَطْوِ","أُطْوُ dan لَا تَطْوُ","اِطْوَ dan لَا تَطْوَ","طَوِّ dan لَا تُطَوِّ"],"correct":"اِطْوِ dan لَا تَطْوِ","explanation":"Tanda jazam Fi'il Amr dan Nahi pada Bina' Naqish/Lafif adalah membuang lam fi'il (huruf 'illat Ya'). Dari يَطْوِي menjadi اِطْوِ (dengan hamzah washol kasrah) dan لَا تَطْوِ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz طَوَى?","options":["طَاوٍ dan مَطْوِيٌّ","طَاوِيٌ dan مَطْوُويٌ","طَوِيٌّ dan مَطْوًى","مُطْوٍ dan مُطْوًى"],"correct":"طَاوٍ dan مَطْوِيٌّ","explanation":"Isim Fa'il asal طَاوِيٌ -> Ya' dibuang pada keadaan rafa'/jar menjadi طَاوٍ. Isim Maf'ul asal مَطْوُويٌ -> Wawu wazan diganti Ya' karena berkumpul Wawu & Ya' di mana yang pertama sukun, lalu di-idgham-kan menjadi مَطْوِيٌّ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz طَوَى dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["طُوِيَ (Madhi) dan يُطْوَى (Mudhori')","طُوِيَ (Madhi) dan يُطْوِي (Mudhori')","طُوَى (Madhi) dan يُطْوَى (Mudhori')","طُوِّيَ (Madhi) dan يُطَوَّى (Mudhori')"],"correct":"طُوِيَ (Madhi) dan يُطْوَى (Mudhori')","explanation":"Madhi Majhul: طُوِيَ (di-dhommah awal, di-kasrah sebelum akhir). Mudhori' Majhul: يُطْوَى (di-dhommah huruf mudhoro'ah, dan Ya' lam fi'il diganti Alif Maqshurah karena berharakat setelah fathah)."},"9":{"question":"Bagaimana penyesuaian bentuk Isim Zaman, Isim Makan, dan Isim Alat dari lafadz طَوَى menurut kaidah I'lal?","options":["Isim Zaman/Makan adalah مَطْوًى dan Isim Alat adalah مِطْوًى, berasal dari مَطْوَيٌ dan مِطْوَيٌ yang Ya'-nya diganti Alif Maqshurah karena berharakat setelah fathah","Isim Zaman/Makan adalah مَطْوِيٌّ dan Isim Alat adalah مِطْوِيٌّ","Isim Zaman/Makan adalah مَطْوَاعٌ dan Isim Alat adalah مِطْوَاعٌ","Seluruhnya dibentuk tanpa proses I'lal"],"correct":"Isim Zaman/Makan adalah مَطْوًى dan Isim Alat adalah مِطْوًى, berasal dari مَطْوَيٌ dan مِطْوَيٌ yang Ya'-nya diganti Alif Maqshurah karena berharakat setelah fathah","explanation":"Bentuk asal Isim Zaman/Makan مَطْوَيٌ dan Isim Alat مِطْوَيٌ. Sesuai kaidah I'lal, huruf 'illat Ya' berharakat yang jatuh sesudah fathah diubah menjadi Alif Maqshurah bertanwin, menjadi مَطْوًى dan مِطْوًى."}}}]},{"id_kalimat":"amogenz_tasrif_014","teks_kalimat":"وَضَعَ","analysis":[{"id_lafadz":"amogenz_lafadz_014","word":"وَضَعَ","steps":{"1":{"question":"Apa Wazan dan Bab dari lafadz وَضَعَ dalam Tasrif Ishtilahi?","options":["Bab 3 (فَعَلَ - يَفْعَلُ) dengan wazan asal وَضَعَ - يَوْضَعُ","Bab 1 (فَعَلَ - يَفْعُلُ) dengan wazan asal وَضَعَ - يَوْضُعُ","Bab 2 (فَعَلَ - يَفْعِلُ) dengan wazan asal وَضَعَ - يَوْضِعُ","Bab 4 (فَعِلَ - يَفْعَلُ) dengan wazan asal وَضِعَ - يَوْضَعُ"],"correct":"Bab 3 (فَعَلَ - يَفْعَلُ) dengan wazan asal وَضَعَ - يَوْضَعُ","explanation":"Lafadz وَضَعَ tergolong Bab 3 Thulathi Mujarrad (فَعَلَ - يَفْعَلُ) karena 'ain fi'il-nya (Dhad) atau lam fi'il-nya (Ain) termasuk huruf Halq. Bentuk dasarnya sebelum dibuang Wawu adalah وَضَعَ - يَوْضَعُ."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz وَضَعَ?","options":["وَضَعَ - يَضَعُ - وَضْعًا - فَهُوَ وَاضِعٌ - وَذَاكَ مَوْضُوعٌ - ضَعْ - لَا تَضَعْ - مَوْضِعٌ - مَوْضِعٌ - مِوضَاعٌ","وَضَعَ - يَوْضَعُ - وَضْعًا - فَهُوَ وَاضِعٌ - وَذَاكَ مَوْضُوعٌ - اِوْضَعْ - لَا تَوْضَعْ - مَوْضَعٌ - مَوْضَعٌ - مِوضَاعٌ","وَضَعَ - يَضِعُ - وَضْعًا - فَهُوَ وَاضِعٌ - وَذَاكَ مَوْضُوعٌ - ضِعْ - لَا تَضِعْ - مَوْضِعٌ - مَوْضِعٌ - مِوضَاعٌ","وَضَعَ - يَضَعُ - زِضَعَةً - فَهُوَ مَوْضُوعٌ - وَذَاكَ وَاضِعٌ - ضَعْ - لَا تَضَعْ - مَوْضَعٌ - مَوْضَعٌ - مِوضَاعٌ"],"correct":"وَضَعَ - يَضَعُ - وَضْعًا - فَهُوَ وَاضِعٌ - وَذَاكَ مَوْضُوعٌ - ضَعْ - لَا تَضَعْ - مَوْضِعٌ - مَوْضِعٌ - مِوضَاعٌ","explanation":"Susunan Ishtilahi utuh untuk وَضَعَ: Madhi وَضَعَ, Mudhori' يَضَعُ, Masdar وَضْعًا, Isim Fa'il وَاضِعٌ, Isim Maf'ul مَوْضُوعٌ, Amr ضَعْ, Nahi لَا تَضَعْ, Zaman/Makan مَوْضِعٌ, Isim Alat مِوضَاعٌ."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz وَضَعَ ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["وَضَعْتُمْ","وَضَعُوا","وَضَعْنَ","وَضَعْتُنَّ"],"correct":"وَضَعْتُمْ","explanation":"Untuk dhomir أَنْتُمْ, Fi'il Madhi وَضَعَ di-sukun-kan lam fi'il-nya (ع) dan ditambahi dhomir rafa' mutaharrik Tum (تُمْ), menjadi وَضَعْتُمْ."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz وَضَعَ ketika bertemu dhomir Hum (هُمْ)?","options":["يَضَعُونَ","يَوْضَعُونَ","تَضَعُونَ","يَضَعْنَ"],"correct":"يَضَعُونَ","explanation":"Fi'il Mudhori' dari وَضَعَ adalah يَضَعُ (setelah Wawu dibuang). Ketika bersambung dhomir هُمْ, ditambah Wawu Jama' dan Nun Tsubut menjadi يَضَعُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Mithal Wawi Bab 3 pada pola tasrifan lafadz وَضَعَ?","options":["Huruf Wawu fa' fi'il dibuang pada Fi'il Mudhori' (يَضَعُ) karena jatuh sesudah fathah huruf mudhoro'ah dan terdapat huruf Halq pada 'ain/lam fi'il-nya","Huruf Wawu diganti Alif pada bentuk Fi'il Madhi","Huruf Wawu dibuang pada seluruh bentuk tasrifan tanpa sisa","Huruf Wawu di-idgham-kan ke huruf berikutnya"],"correct":"Huruf Wawu fa' fi'il dibuang pada Fi'il Mudhori' (يَضَعُ) karena jatuh sesudah fathah huruf mudhoro'ah dan terdapat huruf Halq pada 'ain/lam fi'il-nya","explanation":"Mithal Wawi Bab 3 membuang Wawu pada Mudhori' (يَوْضَعُ -> يَضَعُ) untuk menyamakan dengan Bab 2 serta dipengaruhi oleh keberadaan huruf Halq."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz وَضَعَ?","options":["ضَعْ dan لَا تَضَعْ","اِوْضَعْ dan لَا تَوْضَعْ","ضِعْ dan لَا تَضِعْ","أَوْضِعْ dan لَا تُوضِعْ"],"correct":"ضَعْ dan لَا تَضَعْ","explanation":"Fi'il Amr dibuat dari mudhori' تَضَعُ. Dibuang huruf mudhoro'ah (تَـ), tersisa ضَعْ (tanpa butuh hamzah washol karena huruf awal berharakat fathah). Nahinya لَا تَضَعْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz وَضَعَ?","options":["وَاضِعٌ dan مَوْضُوعٌ","مُوضِعٌ dan مُوضَعٌ","وَضِيعٌ dan مَوْضَعٌ","وَاضٍ dan مَوْضِيٌّ"],"correct":"وَاضِعٌ dan مَوْضُوعٌ","explanation":"Isim Fa'il mengikuti wazan فَاعِلٌ menjadi وَاضِعٌ (Wawu utuh di awal). Isim Maf'ul mengikuti wazan مَفْعُولٌ menjadi مَوْضُوعٌ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz وَضَعَ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["وُضِعَ (Madhi) dan يُوضَعُ (Mudhori')","وُضِعَ (Madhi) dan يُضَعُ (Mudhori')","وَضِعَ (Madhi) dan يُوضِعُ (Mudhori')","وُضِّعَ (Madhi) dan يُوَضَّعُ (Mudhori')"],"correct":"وُضِعَ (Madhi) dan يُوضَعُ (Mudhori')","explanation":"Madhi Majhul: وُضِعَ. Pada Mudhori' Majhul يُوضَعُ, huruf Wawu dikembalikan lagi (tidak dibuang) karena huruf sebelum Wawu berharakat dhommah."},"9":{"question":"Bagaimana ketentuan wazan Isim Zaman dan Isim Makan khusus dari lafadz وَضَعَ (Bina' Mithal Wawi)?","options":["Mengikuti wazan مَفْعِلٌ (مَوْضِعٌ) dengan 'ain fi'il di-kasrah-kan secara khusus sebagai kaidah muttharid Bina' Mithal Wawi, meskipun fi'il mudhori'-nya berharakat fathah","Mengikuti wazan مَفْعَلٌ (مَوْضَعٌ) karena mudhori'-nya fathah","Mengikuti wazan مَفْعُولٌ (مَوْضُوعٌ)","Tidak dapat dibentuk Isim Zaman dan Isim Makan-nya"],"correct":"Mengikuti wazan مَفْعِلٌ (مَوْضِعٌ) dengan 'ain fi'il di-kasrah-kan secara khusus sebagai kaidah muttharid Bina' Mithal Wawi, meskipun fi'il mudhori'-nya berharakat fathah","explanation":"Sesuai kaidah Shorof, Isim Zaman dan Isim Makan dari Bina' Mithal Wawi secara baku/muttharid selalu ber-wazan مَفْعِلٌ (kasrah 'ain), seperti مَوْضِعٌ dan مَوْعِدٌ."}}}]},{"id_kalimat":"amogenz_tasrif_015","teks_kalimat":"سَأَلَ","analysis":[{"id_lafadz":"amogenz_lafadz_015","word":"سَأَلَ","steps":{"1":{"question":"Apa Wazan dan Bab dari lafadz سَأَلَ dalam Tasrif Ishtilahi?","options":["Bab 3 (فَعَلَ - يَفْعَلُ)","Bab 1 (فَعَلَ - يَفْعُلُ)","Bab 2 (فَعَلَ - يَفْعِلُ)","Bab 4 (فَعِلَ - يَفْعَلُ)"],"correct":"Bab 3 (فَعَلَ - يَفْعَلُ)","explanation":"Lafadz سَأَلَ tergolong Bab 3 Thulathi Mujarrad (فَعَلَ - يَفْعَلُ) karena 'ain fi'il-nya berupa huruf Halq (Hamzah), sehingga menjadi سَأَلَ - يَسْأَلُ."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz سَأَلَ?","options":["سَأَلَ - يَسْأَلُ - سُؤَالًا - فَهُوَ سَائِلٌ - وَذَاكَ مَسْئُولٌ - اِسْأَلْ - لَا تَسْأَلْ - مَسْأَلٌ - مَسْأَلٌ - مِسْأَلٌ","سَأَلَ - يَسْئِلُ - سُؤَالًا - فَهُوَ سَائِلٌ - وَذَاكَ مَسْئُولٌ - اِسْئِلْ - لَا تَسْئِلْ - مَسْئِلٌ - مَسْئِلٌ - مِسْأَلٌ","سَأَلَ - يَسْأُلُ - سُؤَالًا - فَهُوَ مَسْئُولٌ - وَذَاكَ سَائِلٌ - أُسْأُلْ - لَا تَسْأُلْ - مَسْأَلٌ - مَسْأَلٌ - مِسْأَلٌ","سَأَلَ - يَسْأَلُ - سَأْلًا - فَهُوَ سَائِلٌ - وَذَاكَ مَسْأُولٌ - اِسْأَلْ - لَا تَسْأَلْ - مَسْأَلٌ - مَسْأَلٌ - مِسْأَلٌ"],"correct":"سَأَلَ - يَسْأَلُ - سُؤَالًا - فَهُوَ سَائِلٌ - وَذَاكَ مَسْئُولٌ - اِسْأَلْ - لَا تَسْأَلْ - مَسْأَلٌ - مَسْأَلٌ - مِسْأَلٌ","explanation":"Tasrif Ishtilahi utuh dari سَأَلَ: Madhi سَأَلَ, Mudhori' يَسْأَلُ, Masdar سُؤَالًا, Isim Fa'il سَائِلٌ, Isim Maf'ul مَسْئُولٌ, Amr اِسْأَلْ, Nahi لَا تَسْأَلْ, Zaman/Makan مَسْأَلٌ, Isim Alat مِسْأَلٌ."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz سَأَلَ ketika bertemu dhomir Ana (أَنَا)?","options":["سَأَلْتُ","سُئِلْتُ","سَأَلْنَا","سَأَلُوا"],"correct":"سَأَلْتُ","explanation":"Untuk dhomir أَنَا, Fi'il Madhi سَأَلَ di-sukun-kan lam fi'il-nya (ل) dan ditambahi dhomir Tu (تُ), menjadi سَأَلْتُ."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz سَأَلَ ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["تَسْأَلُونَ","يَسْأَلُونَ","تَسْأَلَانِ","تَسْأَلْنَ"],"correct":"تَسْأَلُونَ","explanation":"Untuk dhomir أَنْتُمْ, Fi'il Mudhori' يَسْأَلُ diawali Ta' mudhoro'ah dan diakhiri Wawu Jama' serta Nun Tsubut, menjadi تَسْأَلُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Mahmuz 'Ain pada pola tasrifan lafadz سَأَلَ?","options":["Huruf 'ain fi'il berupa Hamzah. Seluruh hurufnya tetap utuh dan penulisan hamzah disesuaikan dengan harakat hamzah serta harakat huruf sebelumnya","Hamzah dibuang pada seluruh bentuk tasrifan","Hamzah diganti menjadi huruf 'illat Ya' di seluruh bentuk","Di-idgham-kan ke huruf lam fi'il"],"correct":"Huruf 'ain fi'il berupa Hamzah. Seluruh hurufnya tetap utuh dan penulisan hamzah disesuaikan dengan harakat hamzah serta harakat huruf sebelumnya","explanation":"Bina' Mahmuz 'Ain pada lafadz سَأَلَ mempertahankan huruf-huruf utuhnya, dengan kaidah penulisan Rasm Hamzah sesuai tingkat kekuatan harakat."},"6":{"question":"Apa bentuk Fi'il Amr baku dan Fi'il Nahi dari lafadz سَأَلَ?","options":["اِسْأَلْ dan لَا تَسْأَلْ","سُؤَلْ dan لَا تَسُؤَلْ","اِسْأِلْ dan لَا تَسْأِلْ","أَسْئِلْ dan لَا تُسْئِلْ"],"correct":"اِسْأَلْ dan لَا تَسْأَلْ","explanation":"Fi'il Amr baku dibentuk dari mudhori' majzum تَسْأَلْ dengan menambah hamzah washol kasrah menjadi اِسْأَلْ. Nahinya لَا تَسْأَلْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz سَأَلَ?","options":["سَائِلٌ dan مَسْئُولٌ","سَأَلٌ dan مَسْأَلٌ","مُسْئِلٌ dan مُسْئَلٌ","سَائِلٌ dan مَسْآلٌ"],"correct":"سَائِلٌ dan مَسْئُولٌ","explanation":"Isim Fa'il mengikuti wazan فَاعِلٌ (سَائِلٌ - hamzah ditulis di atas Ya' karena kasrah). Isim Maf'ul mengikuti wazan مَفْعُولٌ (مَسْئُولٌ)."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz سَأَلَ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["سُئِلَ (Madhi) dan يُسْأَلُ (Mudhori')","سُأِلَ (Madhi) dan يُسْئَلُ (Mudhori')","سُؤِلَ (Madhi) dan يُسْأُلُ (Mudhori')","سُئِّلَ (Madhi) dan يُسَأَّلُ (Mudhori')"],"correct":"سُئِلَ (Madhi) dan يُسْأَلُ (Mudhori')","explanation":"Madhi Majhul: سُئِلَ (di-dhommah awal, di-kasrah sebelum akhir, hamzah ditulis di atas Ya'). Mudhori' Majhul: يُسْأَلُ (di-dhommah huruf mudhoro'ah, dan di-fathah 'ain fi'il, hamzah ditulis di atas Alif)."},"9":{"question":"Bagaimana bentuk variasi Fi'il Amr khusus dari lafadz سَأَلَ untuk takhfif (peringanan)?","options":["Boleh diucapkan سَلْ dengan membuang hamzah 'ain fi'il beserta pemindahan harakatnya, di samping bentuk aslinya اِسْأَلْ","Boleh diucapkan سُؤْ tanpa huruf lam fi'il","Boleh diucapkan أُسْلُ dengan mengganti hamzah menjadi Wawu","Tidak memiliki bentuk variasi lain"],"correct":"Boleh diucapkan سَلْ dengan membuang hamzah 'ain fi'il beserta pemindahan harakatnya, di samping bentuk aslinya اِسْأَلْ","explanation":"Di samping bentuk asal اِسْأَلْ, lafadz سَأَلَ memiliki variasi Fi'il Amr khusus yaitu سَلْ (dengan memindah fathah hamzah ke Sin lalu membuang hamzah demi takhfif)."}}}]},{"id_kalimat":"amogenz_tasrif_016","teks_kalimat":"فَتَحَ","analysis":[{"id_lafadz":"amogenz_lafadz_016","word":"فَتَحَ","steps":{"1":{"question":"Apa Wazan dan Bab dari lafadz فَتَحَ dalam Tasrif Ishtilahi?","options":["Bab 3 (فَعَلَ - يَفْعَلُ)","Bab 1 (فَعَلَ - يَفْعُلُ)","Bab 2 (فَعَلَ - يَفْعِلُ)","Bab 4 (فَعِلَ - يَفْعَلُ)"],"correct":"Bab 3 (فَعَلَ - يَفْعَلُ)","explanation":"Lafadz فَتَحَ tergolong Thulathi Mujarrad Bab 3 (فَعَلَ - يَفْعَلُ) dengan syarat 'ain fi'il atau lam fi'il-nya berupa huruf Halq (Ha' Ha')."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz فَتَحَ?","options":["فَتَحَ - يَفْتَحُ - فَتْحًا - فَهُوَ فَاتِحٌ - وَذَاكَ مَفْتُوحٌ - اِفْتَحْ - لَا تَفْتَحْ - مَفْتَحٌ - مَفْتَحٌ - مِفْتَاحٌ","فَتَحَ - يَفْتِحُ - فَتْحًا - فَهُوَ فَاتِحٌ - وَذَاكَ مَفْتُوحٌ - اِفْتِحْ - لَا تَفْتِحْ - مَفْتِحٌ - مَفْتِحٌ - مِفْتَاحٌ","فَتَحَ - يَفْتُحُ - فَتْحًا - فَهُوَ فَاتِحٌ - وَذَاكَ مَفْتُوحٌ - أُفْتُحْ - لَا تَفْتُحْ - مَفْتَحٌ - مَفْتَحٌ - مِفْتَاحٌ","فَتَحَ - يَفْتَحُ - فُتُوحًا - فَهُوَ مَفْتُوحٌ - وَذَاكَ فَاتِحٌ - اِفْتَحْ - لَا تَفْتَحْ - مَفْتَحٌ - مَفْتَحٌ - مِفْتَاحٌ"],"correct":"فَتَحَ - يَفْتَحُ - فَتْحًا - فَهُوَ فَاتِحٌ - وَذَاكَ مَفْتُوحٌ - اِفْتَحْ - لَا تَفْتَحْ - مَفْتَحٌ - مَفْتَحٌ - مِفْتَاحٌ","explanation":"Tasrif Ishtilahi utuh dari فَتَحَ: Madhi فَتَحَ, Mudhori' يَفْتَحُ, Masdar فَتْحًا, Isim Fa'il فَاتِحٌ, Isim Maf'ul مَفْتُوحٌ, Amr اِفْتَحْ, Nahi لَا تَفْتَحْ, Zaman/Makan مَفْتَحٌ, Isim Alat مِفْتَاحٌ."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz فَتَحَ ketika bertemu dhomir Hum (هُمْ)?","options":["فَتَحُوا","فَتَحَا","فَتَحْنَ","فَتَحْتُمْ"],"correct":"فَتَحُوا","explanation":"Ketika Fi'il Madhi فَتَحَ bersambung dhomir jama' mudzakkar ghaib (هُمْ), lam fi'il (ح) di-dhommah-kan dan ditambah Wawu Jama' + Alif Tafriq menjadi فَتَحُوا."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz فَتَحَ ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["تَفْتَحُونَ","يَفْتَحُونَ","تَفْتَحَانِ","تَفْتَحْنَ"],"correct":"تَفْتَحُونَ","explanation":"Untuk dhomir أَنْتُمْ, Fi'il Mudhori' يَفْتَحُ diawali Ta' mudhoro'ah dan diakhiri Wawu Jama' serta Nun Tsubut, menjadi تَفْتَحُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Shahih Salim pada pola tasrifan lafadz فَتَحَ?","options":["Seluruh huruf asal (ف, ت, ح) terbebas dari huruf 'illat, hamzah, dan tadh'if sehingga seluruh konjugasi tasrifan berjalan utuh tanpa i'lal","Huruf lam fi'il-nya dibuang pada saat bersambung dhomir mutaharrik","Terjadi penggabungan dua huruf sejenis pada bentuk fi'il amr","Huruf 'ain fi'il-nya diganti menjadi huruf 'illat Alif"],"correct":"Seluruh huruf asal (ف, ت, ح) terbebas dari huruf 'illat, hamzah, dan tadh'if sehingga seluruh konjugasi tasrifan berjalan utuh tanpa i'lal","explanation":"Bina' Shahih Salim membuat konjugasi lafadz فَتَحَ berjalan secara kiasiy baku tanpa ada pembungan huruf, pengoperan harakat, atau peleburan."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz فَتَحَ?","options":["اِفْتَحْ dan لَا تَفْتَحْ","اِفْتِحْ dan لَا تَفْتِحْ","أُفْتُحْ dan لَا تَفْتُحْ","فَتِّحْ dan لَا تُفَتِّحْ"],"correct":"اِفْتَحْ dan لَا تَفْتَحْ","explanation":"Fi'il Amr dibentuk dari mudhori' majzum تَفْتَحْ dengan menambah Hamzah Washol kasrah (karena 'ain fi'il fathah) menjadi اِفْتَحْ. Nahinya لَا تَفْتَحْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz فَتَحَ?","options":["فَاتِحٌ dan مَفْتُوحٌ","مُفْتِحٌ dan مُفْتَحٌ","فَتِيحٌ dan مَفْتَحٌ","فَاتِحٌ dan مُفَتَّحٌ"],"correct":"فَاتِحٌ dan مَفْتُوحٌ","explanation":"Isim Fa'il Thulathi Mujarrad mengikuti wazan فَاعِلٌ (فَاتِحٌ) dan Isim Maf'ul mengikuti wazan مَفْعُولٌ (مَفْتُوحٌ)."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz فَتَحَ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["فُتِحَ (Madhi) dan يُفْتَحُ (Mudhori')","فَتَحَ (Madhi) dan يَفْتَحُ (Mudhori')","فُتِحَ (Madhi) dan يُفْتِحُ (Mudhori')","فُتِّحَ (Madhi) dan يُفَتَّحُ (Mudhori')"],"correct":"فُتِحَ (Madhi) dan يُفْتَحُ (Mudhori')","explanation":"Madhi Majhul di-dhommah awal dan di-kasrah sebelum akhir (فُتِحَ). Mudhori' Majhul di-dhommah huruf mudhoro'ah dan di-fathah sebelum akhir (يُفْتَحُ)."}}}]},{"id_kalimat":"amogenz_tasrif_017","teks_kalimat":"فَرَّ","analysis":[{"id_lafadz":"amogenz_lafadz_017","word":"فَرَّ","steps":{"1":{"question":"Apa Wazan asli dan Bab dari lafadz فَرَّ dalam Tasrif Ishtilahi?","options":["Bab 2 (فَعَلَ - يَفْعِلُ) dengan bentuk asal فَرَرَ - يَفْرِرُ","Bab 1 (فَعَلَ - يَفْعُلُ) dengan bentuk asal فَرَرَ - يَفْرُرُ","Bab 4 (فَعِلَ - يَفْعَلُ) dengan bentuk asal فَرِرَ - يَفْرَرُ","Bab 3 (فَعَلَ - يَفْعَلُ) dengan bentuk asal فَرَرَ - يَفْرَرُ"],"correct":"Bab 2 (فَعَلَ - يَفْعِلُ) dengan bentuk asal فَرَرَ - يَفْرِرُ","explanation":"Lafadz فَرَّ tergolong Bab 2 Thulathi Mujarrad. Bentuk aslinya sebelum terjadi idgham adalah فَرَرَ (Madhi) dan يَفْرِرُ (Mudhori')."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz فَرَّ?","options":["فَرَّ - يَفِرُّ - فِرَارًا - فَهُوَ فَارٌّ - وَذَاكَ مَفْرُورٌ - فِرَّ - لَا تَفِرَّ - مَفِرٌّ - مَفِرٌّ - مِفَرٌّ","فَرَّ - يَفُرُّ - فَرًّا - فَهُوَ فَارٌّ - وَذَاكَ مَفْرُورٌ - فُرَّ - لَا تَفُرَّ - مَفَرٌّ - مَفَرٌّ - مِفَرٌّ","فَرَرَ - يَفْرِرُ - فِرَارًا - فَهُوَ فَارِرٌ - وَذَاكَ مَفْرُورٌ - اِفْرِرْ - لَا تَفْرِرْ - مَفْرِرٌ - مَفْرِرٌ - مِفْرَرٌ","فَرَّ - يَفِرُّ - فَرًّا - فَهُوَ مَفْرُورٌ - وَذَاكَ فَارٌّ - فِرَّ - لَا تَفِرَّ - مَفَرٌّ - مَفَرٌّ - مِفَرٌّ"],"correct":"فَرَّ - يَفِرُّ - فِرَارًا - فَهُوَ فَارٌّ - وَذَاكَ مَفْرُورٌ - فِرَّ - لَا تَفِرَّ - مَفِرٌّ - مَفِرٌّ - مِفَرٌّ","explanation":"Tasrif Ishtilahi utuh ter-idgham dari فَرَّ: Madhi فَرَّ, Mudhori' يَفِرُّ, Masdar فِرَارًا, Isim Fa'il فَارٌّ, Isim Maf'ul مَفْرُورٌ, Amr فِرَّ, Nahi لَا تَفِرَّ, Zaman/Makan مَفِرٌّ, Isim Alat مِفَرٌّ."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz فَرَّ ketika bertemu dhomir Hunna (هُنَّ)?","options":["فَرَرْنَ","فَرَّنَ","فَرُّوا","فَرَرْتُنَّ"],"correct":"فَرَرْنَ","explanation":"Ketika bersambung dhomir rafa' mutaharrik seperti Hunna (هُنَّ), lam fi'il (Ra' kedua) di-sukun-kan, sehingga idgham wajib dilepas (فك الإدغام) menjadi فَرَرْنَ."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz فَرَّ ketika bertemu dhomir Antunna (أَنْتُنَّ)?","options":["تَفْرِرْنَ","تَفِرَّنَ","تَفِرُّونَ","تَفْرِرْنَّ"],"correct":"تَفْرِرْنَ","explanation":"Pada Fi'il Mudhori' bersambung dhomir Nun Niswah (أَنْتُنَّ), terjadi fakk al-idgham (penguraian dua huruf sejenis) karena lam fi'il sukun, mengembalikan bentuk asal menjadi تَفْرِرْنَ."},"5":{"question":"Bagaimana pengaruh Bina' Mudho'af Bab 2 pada pola tasrifan lafadz فَرَّ?","options":["Dua huruf Ra' di-idgham-kan menjadi bertasydid saat keduanya berharakat, dan wajib diurai (fakk) saat bertemu dhomir rafa' mutaharrik","Dua huruf Ra' dibuang salah satunya di seluruh konjugasi","Huruf Ra' kedua diganti menjadi Alif pada bentuk Fi'il Madhi","Tidak terjadi kaidah idgham sama sekali"],"correct":"Dua huruf Ra' di-idgham-kan menjadi bertasydid saat keduanya berharakat, dan wajib diurai (fakk) saat bertemu dhomir rafa' mutaharrik","explanation":"Bina' Mudho'af Bab 2 (فَرَرَ - يَفْرِرُ) mewajibkan idgham jika huruf sejenis berharakat dan fakk al-idgham jika bersambung dhomir rafa' mutaharrik."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz فَرَّ untuk dhomir Anta (أَنْتَ)?","options":["فِرَّ (atau اِفْرِرْ) dan لَا تَفِرَّ (atau لَا تَفْرِرْ)","أُفْرُرْ dan لَا تَفْرُرْ","فَرِّ dan لَا تَفَرَّ","فُرَّ dan لَا تَفُرَّ"],"correct":"فِرَّ (atau اِفْرِرْ) dan لَا تَفِرَّ (atau لَا تَفْرِرْ)","explanation":"Fi'il Amr dhomir أَنْتَ dari Mudhori' Bab 2 (يَفِرُّ) boleh di-idgham-kan (فِرَّ) atau diurai lepas idgham (اِفْرِرْ). Demikian pula Nahi-nya: لَا تَفِرَّ / لَا تَفْرِرْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz فَرَّ?","options":["فَارٌّ dan مَفْرُورٌ","فَارِرٌ dan مَفْرُورٌ","مُفِرٌّ dan مُفَرٌّ","فَارٍ dan مَفْرِيٌّ"],"correct":"فَارٌّ dan مَفْرُورٌ","explanation":"Isim Fa'il asal فَارِرٌ di-idgham-kan menjadi فَارٌّ. Isim Maf'ul wazan مَفْعُولٌ tidak di-idgham-kan karena dipisahkan oleh Wawu sukun, tetap مَفْرُورٌ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz فَرَّ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["فُرَّ (Madhi) dan يُفَرُّ (Mudhori')","فَرَّ (Madhi) dan يَفِرُّ (Mudhori')","فُرِرَ (Madhi) dan يُفْرَرُ (Mudhori')","فُرَّ (Madhi) dan يُفِرُّ (Mudhori')"],"correct":"فُرَّ (Madhi) dan يُفَرُّ (Mudhori')","explanation":"Madhi Majhul asal فُرِرَ di-idgham-kan menjadi فُرَّ. Mudhori' Majhul asal يُفْرَرُ, harakat fathah Ra' pertama dipindah ke Fa' lalu di-idgham-kan menjadi يُفَرُّ."},"9":{"question":"Bagaimana wazan Isim Zaman dan Isim Makan khusus dari lafadz فَرَّ (Bina' Mudho'af Bab 2)?","options":["Ber-wazan مَفْعِلٌ (مَفْرِرٌ -> مَفِرٌّ) dengan kasrah 'ain fi'il karena berasal dari Fi'il Mudhori' kasrah 'ain (يَفِرُّ)","Ber-wazan مَفْعَلٌ (مَفَرٌّ) tanpa pengaruh fi'il mudhori'-nya","Ber-wazan مَفْعُولٌ (مَفْرُورٌ)","Tidak dapat dibentuk Isim Zaman dan Makan-nya"],"correct":"Ber-wazan مَفْعِلٌ (مَفْرِرٌ -> مَفِرٌّ) dengan kasrah 'ain fi'il karena berasal dari Fi'il Mudhori' kasrah 'ain (يَفِرُّ)","explanation":"Isim Zaman/Makan dari Thulathi Mujarrad yang mudhori'-nya berharakat kasrah 'ain (Bab 2 فَعَلَ - يَفْعِلُ) wajib ber-wazan مَفْعِلٌ, sehingga asal مَفْرِرٌ di-idgham-kan menjadi مَفِرٌّ."}}}]},{"id_kalimat":"amogenz_tasrif_018","teks_kalimat":"قَضَى","analysis":[{"id_lafadz":"amogenz_lafadz_018","word":"قَضَى","steps":{"1":{"question":"Apa Wazan asli dan Bab dari lafadz قَضَى dalam Tasrif Ishtilahi?","options":["Bab 2 (فَعَلَ - يَفْعِلُ) dengan wazan asal قَضَيَ - يَقْضِيُ","Bab 1 (فَعَلَ - يَفْعُلُ) dengan wazan asal قَضَوَ - يَقْضُوُ","Bab 3 (فَعَلَ - يَفْعَلُ) dengan wazan asal قَضَيَ - يَقْضَيُ","Bab 4 (فَعِلَ - يَفْعَلُ) dengan wazan asal قَضِيَ - يَقْضَيُ"],"correct":"Bab 2 (فَعَلَ - يَفْعِلُ) dengan wazan asal قَضَيَ - يَقْضِيُ","explanation":"Lafadz قَضَى tergolong Bab 2 Thulathi Mujarrad. Bentuk dasarnya sebelum proses i'lal adalah قَضَيَ - يَقْضِيُ."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz قَضَى?","options":["قَضَى - يَقْضِي - قَضَاءً - فَهُوَ قَاضٍ - وَذَاكَ مَقْضِيٌّ - اِقْضِ - لَا تَقْضِ - مَقْضًى - مَقْضًى - مِقْضًى","قَضَى - يَقْضَى - قَضْيًا - فَهُوَ قَاضٍ - وَذَاكَ مَقْضًى - اِقْضَ - لَا تَقْضَ - مَقْضًى - مَقْضًى - مِقْضًى","قَضَى - يَقْضِي - قَضِيَّةً - فَهُوَ مَقْضِيٌّ - وَذَاكَ قَاضٍ - اِقْضِ - لَا تَقْضِ - مَقْضِيٌّ - مَقْضِيٌّ - مِقْضًى","قَضَيَ - يَقْضِيُ - قَضْيًا - فَهُوَ قَاضِيٌ - وَذَاكَ مَقْضُويٌ - اِقْضِيْ - لَا تَقْضِيْ - مَقْضَيٌ - مَقْضَيٌ - مِقْضَيٌ"],"correct":"قَضَى - يَقْضِي - قَضَاءً - فَهُوَ قَاضٍ - وَذَاكَ مَقْضِيٌّ - اِقْضِ - لَا تَقْضِ - مَقْضًى - مَقْضًى - مِقْضًى","explanation":"Tasrif Ishtilahi utuh ter-i'lal dari قَضَى: Madhi قَضَى, Mudhori' يَقْضِي, Masdar قَضَاءً, Isim Fa'il قَاضٍ, Isim Maf'ul مَقْضِيٌّ, Amr اِقْضِ, Nahi لَا تَقْضِ, Zaman/Makan مَقْضًى, Isim Alat مِقْضًى."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz قَضَى ketika bertemu dhomir Hum (هُمْ)?","options":["قَضَوْا","قَضَيُوا","قَضُوا","قَضَايُوا"],"correct":"قَضَوْا","explanation":"Bentuk asal قَضَيُوا (dhomir هُمْ) mengalami pembuangan Ya' lam fi'il karena bertemu Wawu Jama' yang sukun, dan Dhad tetap berharakat fathah penanda Ya' terbuang, menjadi قَضَوْا."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz قَضَى ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["تَقْضُونَ","تَقْضِيُونَ","تَقْضَيُونَ","تَقْضِينَ"],"correct":"تَقْضُونَ","explanation":"Pada dhomir أَنْتُمْ, bentuk asal تَقْضِيُونَ mengalami pembuangan dhommah Ya' karena itsqal lalu Ya' dibuang karena iltiqa' sakinain dengan Wawu Jama', Dhad di-dhommah-kan agar sesuai Wawu, menjadi تَقْضُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Naqish Ya'i pada pola tasrifan lafadz قَضَى?","options":["Huruf 'illat Ya' pada قَضَيَ diganti Alif (قَضَى) karena berharakat setelah Fathah, dan dhommah-nya ditiadakan pada Mudhori' (يَقْضِي) karena itsqal","Huruf Ya' diganti Wawu pada seluruh bentuk tasrifan","Huruf Ya' dibuang tanpa sisa pada Fi'il Madhi","Tidak mengalami proses I'lal sama sekali"],"correct":"Huruf 'illat Ya' pada قَضَيَ diganti Alif (قَضَى) karena berharakat setelah Fathah, dan dhommah-nya ditiadakan pada Mudhori' (يَقْضِي) karena itsqal","explanation":"Pada Madhi قَضَيَ, Ya' berharakat sesudah fathah diganti Alif Maqshurah menjadi قَضَى. Pada Mudhori' يَقْضِيُ, dhommah di atas Ya' digugurkan karena berat diucapkan (itsqal)."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz قَضَى?","options":["اِقْضِ dan لَا تَقْضِ","أُقْضُ dan لَا تَقْضُ","اِقْضَى dan لَا تَقْضَى","قَضِّ dan لَا تُقَضِّ"],"correct":"اِقْضِ dan لَا تَقْضِ","explanation":"Tanda jazam Fi'il Amr dan Nahi pada Bina' Naqish adalah membuang lam fi'il (huruf 'illat Ya'). Dari يَقْضِي menjadi اِقْضِ (dengan hamzah washol kasrah) dan لَا تَقْضِ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz قَضَى?","options":["قَاضٍ dan مَقْضِيٌّ","قَاضِيٌ dan مَقْضُويٌ","قَاضٍ dan مَقْضُوٌّ","مُقْضٍ dan مُقْضًى"],"correct":"قَاضٍ dan مَقْضِيٌّ","explanation":"Isim Fa'il asal قَاضِيٌ -> Ya' dibuang pada keadaan rafa'/jar menjadi قَاضٍ. Isim Maf'ul asal مَقْضُويٌ -> Wawu diganti Ya' karena berkumpul Wawu & Ya' di mana yang pertama sukun, lalu di-idgham-kan menjadi مَقْضِيٌّ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz قَضَى dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["قُضِيَ (Madhi) dan يُقْضَى (Mudhori')","قُضِيَ (Madhi) dan يُقْضِي (Mudhori')","قُضَى (Madhi) dan يُقْضَى (Mudhori')","قُضِّيَ (Madhi) dan يُقَضَّى (Mudhori')"],"correct":"قُضِيَ (Madhi) dan يُقْضَى (Mudhori')","explanation":"Madhi Majhul: قُضِيَ (di-dhommah awal, di-kasrah sebelum akhir). Mudhori' Majhul: يُقْضَى (di-dhommah huruf mudhoro'ah, dan Ya' lam fi'il diganti Alif Maqshurah karena berharakat setelah fathah)."},"9":{"question":"Bagaimana pembentukan Masdar, Isim Zaman, dan Isim Makan dari lafadz قَضَى menurut kaidah I'lal?","options":["Masdar asal قَضَايٌ diganti Hamzah menjadi قَضَاءً karena Ya' berada di akhir setelah Alif Zaidah; sedangkan Isim Zaman/Makan adalah مَقْضًى (asal مَقْضَيٌ)","Masdar adalah قَضْيًا dan Isim Zaman adalah مَقْضِيٌّ","Masdar adalah قَضْوَةً dan Isim Zaman adalah مَقْضُوعٌ","Seluruhnya dibentuk tanpa proses I'lal"],"correct":"Masdar asal قَضَايٌ diganti Hamzah menjadi قَضَاءً karena Ya' berada di akhir setelah Alif Zaidah; sedangkan Isim Zaman/Makan adalah مَقْضًى (asal مَقْضَيٌ)","explanation":"Pada Masdar قَضَاءً (asal قَضَايٌ), Ya' ekstremitas setelah Alif Zaidah diubah menjadi Hamzah. Pada Isim Zaman/Makan (مَقْضَيٌ), Ya' berharakat sesudah fathah diganti Alif Maqshurah bertanwin menjadi مَقْضًى."}}}]},{"id_kalimat":"amogenz_tasrif_019","teks_kalimat":"قَرَأَ","analysis":[{"id_lafadz":"amogenz_lafadz_019","word":"قَرَأَ","steps":{"1":{"question":"Apa Wazan dan Bab dari lafadz قَرَأَ dalam Tasrif Ishtilahi?","options":["Bab 3 (فَعَلَ - يَفْعَلُ)","Bab 1 (فَعَلَ - يَفْعُلُ)","Bab 2 (فَعَلَ - يَفْعِلُ)","Bab 4 (فَعِلَ - يَفْعَلُ)"],"correct":"Bab 3 (فَعَلَ - يَفْعَلُ)","explanation":"Lafadz قَرَأَ tergolong Bab 3 Thulathi Mujarrad (فَعَلَ - يَفْعَلُ) karena lam fi'il-nya berupa huruf Halq (Hamzah), sehingga menjadi قَرَأَ - يَقْرَأُ."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz قَرَأَ?","options":["قَرَأَ - يَقْرَأُ - قِرَاءَةً - فَهُوَ قَارِئٌ - وَذَاكَ مَقْرُوءٌ - اِقْرَأْ - لَا تَقْرَأْ - مَقْرَأٌ - مَقْرَأٌ - مِقْرَأٌ","قَرَأَ - يَقْرِئُ - قِرَاءَةً - فَهُوَ قَارِئٌ - وَذَاكَ مَقْرُوءٌ - اِقْرِئْ - لَا تَقْرِئْ - مَقْرِئٌ - مَقْرِئٌ - مِقْرَأٌ","قَرَأَ - يَقْرُؤُ - قِرَاءَةً - فَهُوَ مَقْرُوءٌ - وَذَاكَ قَارِئٌ - أُقْرُؤْ - لَا تَقْرُؤْ - مَقْرَأٌ - مَقْرَأٌ - مِقْرَأٌ","قَرَأَ - يَقْرَأُ - قَرْءًا - فَهُوَ قَارِئٌ - وَذَاكَ مَقْرُوءٌ - اِقْرَأْ - لَا تَقْرَأْ - مَقْرَأٌ - مَقْرَأٌ - مِقْرَأٌ"],"correct":"قَرَأَ - يَقْرَأُ - قِرَاءَةً - فَهُوَ قَارِئٌ - وَذَاكَ مَقْرُوءٌ - اِقْرَأْ - لَا تَقْرَأْ - مَقْرَأٌ - مَقْرَأٌ - مِقْرَأٌ","explanation":"Tasrif Ishtilahi utuh dari قَرَأَ: Madhi قَرَأَ, Mudhori' يَقْرَأُ, Masdar قِرَاءَةً, Isim Fa'il قَارِئٌ, Isim Maf'ul مَقْرُوءٌ, Amr اِقْرَأْ, Nahi لَا تَقْرَأْ, Zaman/Makan مَقْرَأٌ, Isim Alat مِقْرَأٌ."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz قَرَأَ ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["قَرَأْتُمْ","قَرَأُوا","قَرَأْنَ","قَرَأْتُنَّ"],"correct":"قَرَأْتُمْ","explanation":"Untuk dhomir أَنْتُمْ, Fi'il Madhi قَرَأَ di-sukun-kan lam fi'il-nya (Hamzah) dan ditambahi dhomir Tum (تُمْ), sehingga ditulis قَرَأْتُمْ."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz قَرَأَ ketika bertemu dhomir Hum (هُمْ)?","options":["يَقْرَءُونَ (atau يَقْرَؤُونَ)","تَقْرَءُونَ","يَقْرَأَانِ","يَقْرَأْنَ"],"correct":"يَقْرَءُونَ (atau يَقْرَؤُونَ)","explanation":"Untuk dhomir هُمْ, Fi'il Mudhori' يَقْرَأُ diawali Ya' mudhoro'ah dan diakhiri Wawu Jama' serta Nun Tsubut, menjadi يَقْرَءُونَ."},"5":{"question":"Bagaimana pengaruh Bina' Mahmuz Lam pada pola tasrifan lafadz قَرَأَ?","options":["Lam fi'il berupa Hamzah. Seluruh huruf aslinya tetap utuh dan penulisan bentuk rasm Hamzah disesuaikan dengan harakatnya serta harakat huruf sebelumnya","Hamzah dibuang di seluruh bentuk konjugasi tasrifan","Hamzah diganti menjadi huruf 'illat Ya' pada bentuk mudhori'","Di-idgham-kan ke huruf ra' sebelumnya"],"correct":"Lam fi'il berupa Hamzah. Seluruh huruf aslinya tetap utuh dan penulisan bentuk rasm Hamzah disesuaikan dengan harakatnya serta harakat huruf sebelumnya","explanation":"Bina' Mahmuz Lam pada lafadz قَرَأَ tidak merubah struktur dasar kata, melainkan mengikuti kaidah rasm hamzah (misal: di atas Alif pada قَرَأَ, di atas Ya' pada قَارِئٌ, dan berdiri sendiri/di atas Wawu pada مَقْرُوءٌ)."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz قَرَأَ?","options":["اِقْرَأْ dan لَا تَقْرَأْ","اِقْرِئْ dan لَا تَقْرِئْ","أُقْرُؤْ dan لَا تَقْرُؤْ","قَرِّئْ dan لَا تُقَرِّئْ"],"correct":"اِقْرَأْ dan لَا تَقْرَأْ","explanation":"Fi'il Amr dibentuk dari mudhori' majzum تَقْرَأْ dengan menambah Hamzah Washol kasrah (karena 'ain fi'il fathah) menjadi اِقْرَأْ. Nahinya لَا تَقْرَأْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz قَرَأَ?","options":["قَارِئٌ dan مَقْرُوءٌ","قَارَأٌ dan مَقْرَأٌ","مُقْرِئٌ dan مُقْرَأٌ","قَارِئٌ dan مَقْرِيٌّ"],"correct":"قَارِئٌ dan مَقْرُوءٌ","explanation":"Isim Fa'il mengikuti wazan فَاعِلٌ (قَارِئٌ - hamzah ditulis di atas Ya' karena kasrah). Isim Maf'ul mengikuti wazan مَفْعُولٌ (مَقْرُوءٌ)."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz قَرَأَ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["قُرِئَ (Madhi) dan يُقْرَأُ (Mudhori')","قُرَأَ (Madhi) dan يُقْرِئُ (Mudhori')","قُرُؤَ (Madhi) dan يُقْرُأُ (Mudhori')","قُرِّئَ (Madhi) dan يُقَرَّأُ (Mudhori')"],"correct":"قُرِئَ (Madhi) dan يُقْرَأُ (Mudhori')","explanation":"Madhi Majhul: قُرِئَ (di-dhommah awal, di-kasrah sebelum akhir, hamzah di atas Ya'). Mudhori' Majhul: يُقْرَأُ (di-dhommah huruf mudhoro'ah, dan di-fathah sebelum akhir, hamzah di atas Alif)."}}}]},{"id_kalimat":"amogenz_tasrif_020","teks_kalimat":"رَضِيَ","analysis":[{"id_lafadz":"amogenz_lafadz_020","word":"رَضِيَ","steps":{"1":{"question":"Apa Wazan dan Bab dari lafadz رَضِيَ dalam Tasrif Ishtilahi?","options":["Bab 4 (فَعِلَ - يَفْعَلُ)","Bab 2 (فَعَلَ - يَفْعِلُ)","Bab 1 (فَعَلَ - يَفْعُلُ)","Bab 3 (فَعَلَ - يَفْعَلُ)"],"correct":"Bab 4 (فَعِلَ - يَفْعَلُ)","explanation":"Lafadz رَضِيَ merupakan Thulathi Mujarrad Bab 4 (فَعِلَ - يَفْعَلُ), di mana 'ain fi'il di-kasrah-kan pada fi'il madhi dan di-fathah-kan pada fi'il mudhori' (رَضِيَ - يَرْضَى)."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz رَضِيَ?","options":["رَضِيَ - يَرْضَى - رِضْوَانًا - فَهُوَ رَاضٍ - وَذَاكَ مَرْضِيٌّ - اِرْضَ - لَا تَرْضَ - مَرْضًى - مَرْضًى - مِرْضًى","رَضِيَ - يَرْضِي - رَضْيًا - فَهُوَ رَاضِيٌ - وَذَاكَ مَرْضُوٌّ - اِرْضِ - لَا تَرْضِ - مَرْضِيٌّ - مَرْضِيٌّ - مِرْضِيٌّ","رَضِيَ - يَرْضَى - رَضَاءً - فَهُوَ مَرْضِيٌّ - وَذَاكَ رَاضٍ - اِرْضَ - لَا تَرْضَ - مَرْضًى - مَرْضًى - مِرْضًى","رَضِيَ - يَرْضُوَ - رِضًى - فَهُوَ رَاضٍ - وَذَاكَ مَرْضِيٌّ - أُرْضُ - لَا تَرْضُ - مَرْضًى - مَرْضًى - مِرْضًى"],"correct":"رَضِيَ - يَرْضَى - رِضْوَانًا - فَهُوَ رَاضٍ - وَذَاكَ مَرْضِيٌّ - اِرْضَ - لَا تَرْضَ - مَرْضًى - مَرْضًى - مِرْضًى","explanation":"Tasrif Ishtilahi utuh ter-i'lal dari رَضِيَ: Madhi رَضِيَ, Mudhori' يَرْضَى, Masdar رِضْوَانًا, Isim Fa'il رَاضٍ, Isim Maf'ul مَرْضِيٌّ, Amr اِرْضَ, Nahi لَا تَرْضَ, Zaman/Makan مَرْضًى, Isim Alat مِرْضًى."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz رَضِيَ ketika bertemu dhomir Hum (هُمْ)?","options":["رَضُوا","رَضِيُوا","رَضَوْا","رَضِيْنَا"],"correct":"رَضُوا","explanation":"Bentuk asal رَضِيُوا (dhomir هُمْ) mengalami pembuangan dhommah Ya' karena itsqal lalu Ya' dibuang karena iltiqa' sakinain dengan Wawu Jama', Dhad di-dhommah-kan agar sesuai Wawu, menjadi رَضُوا."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz رَضِيَ ketika bertemu dhomir Antum (أَنْتُمْ)?","options":["تَرْضَوْنَ","تَرْضِيُونَ","تَرْضُونَ","تَرْضَيْنَ"],"correct":"تَرْضَوْنَ","explanation":"Pada dhomir أَنْتُمْ dari mudhori' يَرْضَى (asal يَرْضَيُ), Alif Maqshurah dibuang saat bertemu Wawu Jama', dan Dhad tetap berharakat fathah penanda huruf terbuang, menjadi تَرْضَوْنَ."},"5":{"question":"Bagaimana pengaruh Bina' Naqish Ya'i Bab 4 pada pola tasrifan lafadz رَضِيَ?","options":["Huruf Ya' nampak harakat kasrah-nya pada Madhi (رَضِيَ) karena ringan, dan diganti Alif Maqshurah pada Mudhori' (يَرْضَى) karena berharakat sesudah fathah","Huruf Ya' dibuang pada seluruh bentuk tasrifan","Huruf Ya' diganti Wawu pada bentuk Fi'il Madhi","Tidak mengalami proses I'lal sama sekali"],"correct":"Huruf Ya' nampak harakat kasrah-nya pada Madhi (رَضِيَ) karena ringan, dan diganti Alif Maqshurah pada Mudhori' (يَرْضَى) karena berharakat sesudah fathah","explanation":"Pada Naqish Bab 4 (فَعِلَ - يَفْعَلُ), kasrah di atas huruf 'illat Ya' pada Madhi dianggap ringan sehingga tetap nampak (رَضِيَ). Pada Mudhori' يَرْضَيُ, Ya' hidup sesudah fathah diubah jadi Alif (يَرْضَى)."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz رَضِيَ?","options":["اِرْضَ dan لَا تَرْضَ","اِرْضِ dan لَا تَرْضِ","أُرْضُ dan لَا تَرْضُ","رَضِّ dan لَا تُرَضِّ"],"correct":"اِرْضَ dan لَا تَرْضَ","explanation":"Tanda jazam Fi'il Amr dan Nahi pada Bina' Naqish adalah membuang lam fi'il (Alif Maqshurah). Dari يَرْضَى menjadi اِرْضَ (dengan hamzah washol kasrah) dan لَا تَرْضَ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz رَضِيَ?","options":["رَاضٍ dan مَرْضِيٌّ","رَاضِيٌ dan مَرْضُويٌ","رَاضٍ dan مَرْضُوٌّ","مُرْضٍ dan مُرْضًى"],"correct":"رَاضٍ dan مَرْضِيٌّ","explanation":"Isim Fa'il asal رَاضِيٌ -> Ya' dibuang pada keadaan rafa'/jar menjadi رَاضٍ. Isim Maf'ul asal مَرْضُويٌ -> Wawu diganti Ya' karena berkumpul Wawu & Ya' di mana yang pertama sukun, lalu di-idgham-kan menjadi مَرْضِيٌّ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz رَضِيَ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["رُضِيَ (Madhi) dan يُرْضَى (Mudhori')","رُضِيَ (Madhi) dan يُرْضِي (Mudhori')","رُضَى (Madhi) dan يُرْضَى (Mudhori')","رُضِّيَ (Madhi) dan يُرَضَّى (Mudhori')"],"correct":"رُضِيَ (Madhi) dan يُرْضَى (Mudhori')","explanation":"Madhi Majhul: رُضِيَ (di-dhommah awal, di-kasrah sebelum akhir). Mudhori' Majhul: يُرْضَى (di-dhommah huruf mudhoro'ah, dan Ya' diganti Alif Maqshurah karena berharakat setelah fathah)."},"9":{"question":"Bagaimana proses penyesuaian I'lal pada Isim Maf'ul dari lafadz رَضِيَ?","options":["Bentuk asalnya مَرْضُويٌ (wazan مَفْعُولٌ); Wawu diganti Ya' karena berkumpul Wawu dan Ya' dalam satu kata dengan huruf pertama sukun, lalu harakat dhommah sebelum Ya' diubah menjadi kasrah, menghasilkan مَرْضِيٌّ","Bentuk asalnya مَرْضِيٌّ tanpa ada proses I'lal","Bentuk asalnya مَرْضُوٌّ di mana Ya' dibuang","Bentuk asalnya مَرْضَى di mana Wawu diganti Alif"],"correct":"Bentuk asalnya مَرْضُويٌ (wazan مَفْعُولٌ); Wawu diganti Ya' karena berkumpul Wawu dan Ya' dalam satu kata dengan huruf pertama sukun, lalu harakat dhommah sebelum Ya' diubah menjadi kasrah, menghasilkan مَرْضِيٌّ","explanation":"Sesuai Kaidah I'lal: Jika Wawu dan Ya' berkumpul dalam satu kata dan yang pertama sukun, Wawu diubah menjadi Ya' lalu di-idgham-kan. Harakat Dhad di-kasrah-kan agar sesuai dengan Ya' bertasydid (مَرْضِيٌّ)."}}}]},{"id_kalimat":"amogenz_tasrif_021","teks_kalimat":"أَخَذَ","analysis":[{"id_lafadz":"amogenz_lafadz_021","word":"أَخَذَ","steps":{"1":{"question":"Apa Wazan dan Bab dari lafadz أَخَذَ dalam Tasrif Ishtilahi?","options":["Bab 1 (فَعَلَ - يَفْعُلُ)","Bab 2 (فَعَلَ - يَفْعِلُ)","Bab 3 (فَعَلَ - يَفْعَلُ)","Bab 4 (فَعِلَ - يَفْعَلُ)"],"correct":"Bab 1 (فَعَلَ - يَفْعُلُ)","explanation":"Lafadz أَخَذَ tergolong Bab 1 Thulathi Mujarrad (فَعَلَ - يَفْعُلُ), di mana 'ain fi'il-nya di-dhommah-kan pada fi'il mudhori' (أَخَذَ - يَأْخُذُ)."},"2":{"question":"Bagaimana susunan lengkap Tasrif Ishtilahi dari lafadz أَخَذَ?","options":["أَخَذَ - يَأْخُذُ - أَخْذًا - فَهُوَ آخِذٌ - وَذَاكَ مَأْخُوذٌ - خُذْ - لَا تَأْخُذْ - مَأْخَذٌ - مَأْخَذٌ - مِأْخَذٌ","أَخَذَ - يَأْخِذُ - أَخْذًا - فَهُوَ آخِذٌ - وَذَاكَ مَأْخُوذٌ - اِئْخِذْ - لَا تَأْخِذْ - مَأْخِذٌ - مَأْخِذٌ - مِأْخَذٌ","أَخَذَ - يَأْخُذُ - أُخُذًا - فَهُوَ مَأْخُوذٌ - وَذَاكَ آخِذٌ - أُؤْخُذْ - لَا تَأْخُذْ - مَأْخَذٌ - مَأْخَذٌ - مِأْخَذٌ","أَخَذَ - يَأْخَذُ - أَخْذًا - فَهُوَ آخِذٌ - وَذَاكَ مَأْخُوذٌ - اِئْخَذْ - لَا تَأْخَذْ - مَأْخَذٌ - مَأْخَذٌ - مِأْخَذٌ"],"correct":"أَخَذَ - يَأْخُذُ - أَخْذًا - فَهُوَ آخِذٌ - وَذَاكَ مَأْخُوذٌ - خُذْ - لَا تَأْخُذْ - مَأْخَذٌ - مَأْخَذٌ - مِأْخَذٌ","explanation":"Tasrif Ishtilahi utuh dari أَخَذَ: Madhi أَخَذَ, Mudhori' يَأْخُذُ, Masdar أَخْذًا, Isim Fa'il آخِذٌ, Isim Maf'ul مَأْخُوذٌ, Amr خُذْ, Nahi لَا تَأْخُذْ, Zaman/Makan مَأْخَذٌ, Isim Alat مِأْخَذٌ."},"3":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Madhi dari lafadz أَخَذَ ketika bertemu dhomir Anta (أَنْتَ)?","options":["أَخَذْتَ","آخَذْتَ","أَخَذْنَا","أَخَذُوا"],"correct":"أَخَذْتَ","explanation":"Untuk dhomir أَنْتَ, Fi'il Madhi أَخَذَ di-sukun-kan lam fi'il-nya (ذ) dan ditambahi dhomir Ta (تَ), menjadi أَخَذْتَ."},"4":{"question":"Bagaimana bentuk Tasrif Lughawi Fi'il Mudhori' dari lafadz أَخَذَ ketika bertemu dhomir Ana (أَنَا)?","options":["آخُذُ","أَأْخُذُ","نَأْخُذُ","يَأْخُذُ"],"correct":"آخُذُ","explanation":"Bentuk asal dhomir أَنَا pada fi'il mudhori' adalah أَأْخُذُ (berkumpul dua hamzah). Sesuai kaidah I'lal, hamzah kedua yang sukun diganti Alif Mad menjadi آخُذُ."},"5":{"question":"Bagaimana pengaruh Bina' Mahmuz Fa pada pola tasrifan lafadz أَخَذَ?","options":["Fa' fi'il berupa Hamzah. Jika dua hamzah berkumpul di awal kata dengan yang pertama berharakat dan kedua sukun, hamzah kedua diganti huruf Mad yang sesuai harakat hamzah pertama","Hamzah dibuang di seluruh bentuk tasrifan tanpa sisa","Hamzah diganti menjadi huruf 'illat Wawu di seluruh bentuk","Bina' Mahmuz Fa di-idgham-kan ke huruf sesudahnya"],"correct":"Fa' fi'il berupa Hamzah. Jika dua hamzah berkumpul di awal kata dengan yang pertama berharakat dan kedua sukun, hamzah kedua diganti huruf Mad yang sesuai harakat hamzah pertama","explanation":"Lafadz أَخَذَ merupakan Bina' Mahmuz Fa. Kaidah utamanya: saat dua hamzah berkumpul (seperti pada Fi'il Mudhori' dhomir Ana: أَأْخُذُ), hamzah kedua diubah menjadi Alif Mad (آخُذُ)."},"6":{"question":"Apa bentuk Fi'il Amr dan Fi'il Nahi dari lafadz أَخَذَ?","options":["خُذْ dan لَا تَأْخُذْ","أُؤْخُذْ dan لَا تَأْخُذْ","اِئْخُذْ dan لَا تَأْخِذْ","آخُذْ dan لَا تُؤْخُذْ"],"correct":"خُذْ dan لَا تَأْخُذْ","explanation":"Khusus pada Fi'il Amr lafadz أَخَذَ, Hamzah fa' fi'il dibuang secara khusus untuk mempermudah/meringankan pengucapan (تخفيفًا لكثرة الاستعمال) menjadi خُذْ. Nahinya tetap لَا تَأْخُذْ."},"7":{"question":"Apa bentuk Isim Fa'il dan Isim Maf'ul dari lafadz أَخَذَ?","options":["آخِذٌ dan مَأْخُوذٌ","أَاخِذٌ dan مَأْخُوذٌ","مُؤْخِذٌ dan مُؤْخَذٌ","آخِذٌ dan مَأْخِيذٌ"],"correct":"آخِذٌ dan مَأْخُوذٌ","explanation":"Isim Fa'il asal أَاخِذٌ -> Hamzah fa' fi'il bertemu Alif wazan فَاعِلٌ ditulis dengan Alif Mad (آخِذٌ). Isim Maf'ul mengikuti wazan مَفْعُولٌ menjadi مَأْخُوذٌ."},"8":{"question":"Bagaimana bentuk Fi'il Mabni Majhul (pasif) dari lafadz أَخَذَ dalam Fi'il Madhi dan Fi'il Mudhori'?","options":["أُخِذَ (Madhi) dan يُؤْخَذُ (Mudhori')","أُخِذَ (Madhi) dan يُأْخَذُ (Mudhori')","آخِذَ (Madhi) dan يُؤْخُذُ (Mudhori')","أُخِّذَ (Madhi) dan يُؤَخَّذُ (Mudhori')"],"correct":"أُخِذَ (Madhi) dan يُؤْخَذُ (Mudhori')","explanation":"Madhi Majhul: أُخِذَ (di-dhommah awal, di-kasrah sebelum akhir). Mudhori' Majhul: يُؤْخَذُ (di-dhommah huruf mudhoro'ah, Hamzah ditulis di atas Wawu karena sukun sesudah dhommah, dan 'ain fi'il di-fathah-kan)."},"9":{"question":"Mengapa terjadi pembuangan Hamzah fa' fi'il pada Fi'il Amr lafadz أَخَذَ?","options":["Dibuang untuk takhfif (meringankan pengucapan) karena sangat sering digunakan dalam percakapan (لكثرة الاستعمال), sehingga menjadi خُذْ tanpa memerlukan Hamzah Washol","Dibuang karena mengikuti kaidah penimbangan iltiqa' sakinain","Dibuang karena diganti oleh huruf 'illat Ya'","Dibuang karena mengikuti wazan Bab 4"],"correct":"Dibuang untuk takhfif (meringankan pengucapan) karena sangat sering digunakan dalam percakapan (لكثرة الاستعمال), sehingga menjadi خُذْ tanpa memerlukan Hamzah Washol","explanation":"Sebagaimana kaidah Shorof, beberapa fi'il mahmuz fa seperti أَخَذَ (خُذْ), أَكَلَ (كُلْ), dan أَمَرَ (مُرْ) membuang fa' fi'il-nya pada Fi'il Amr demi takhfif akibat frekuensi penggunaan yang sangat tinggi."}}}]}];
